const clientProfile=(headers:Record<string,string|undefined>,rawUserAgent='')=>{const h=(name:string)=>String(headers[name]||headers[name.toLowerCase()]||headers[name.toUpperCase()]||'');const userAgent=rawUserAgent||h('user-agent')||'unknown';const brands=[...h('sec-ch-ua').matchAll(/"([^"]+)";v="([^"]+)"/g)].map(match=>({name:match[1],version:match[2]}));const preferred=brands.find(item=>item.name==='Google Chrome')||brands.find(item=>item.name==='Microsoft Edge')||brands.find(item=>item.name==='Chromium');let browser=preferred?.name==='Microsoft Edge'?'Edge':preferred?.name||'';let browserVersion=preferred?.version||'';if(!browser){const match=/Edg\/(\d+(?:\.\d+)*)/.exec(userAgent)||/OPR\/(\d+(?:\.\d+)*)/.exec(userAgent)||/(?:Chrome|CriOS)\/(\d+(?:\.\d+)*)/.exec(userAgent)||/(?:Firefox|FxiOS)\/(\d+(?:\.\d+)*)/.exec(userAgent)||/Version\/(\d+(?:\.\d+)*).*Safari/.exec(userAgent);if(match){browser=userAgent.includes('Edg/')?'Edge':userAgent.includes('OPR/')?'Opera':/(Firefox|FxiOS)/.test(userAgent)?'Firefox':/Safari/.test(userAgent)&&!/Chrome|CriOS/.test(userAgent)?'Safari':'Chrome';browserVersion=match[1].split('.')[0]}}const platform=h('sec-ch-ua-platform').replace(/"/g,'');const platformVersion=h('sec-ch-ua-platform-version').replace(/"/g,'');let os='',osVersion='';if(platform==='Windows'){const major=Number(platformVersion.split('.')[0]||0);os=major>=13?'Windows 11':major>=10?'Windows 10':'Windows';osVersion=major?platformVersion:''}else if(platform){os=platform;osVersion=platformVersion}if(!os){let match:RegExpExecArray|null;if((match=/Android\s([\d.]+)/.exec(userAgent))){os='Android';osVersion=match[1]}else if((match=/(?:iPhone OS|CPU OS)\s([\d_]+)/.exec(userAgent))){os='iOS';osVersion=match[1].replace(/_/g,'.')}else if((match=/Mac OS X\s([\d_]+)/.exec(userAgent))){os='macOS';osVersion=match[1].replace(/_/g,'.')}else if(/Windows NT 10\.0/.test(userAgent)){os='Windows 10/11'}else if(/Linux/.test(userAgent)){os='Linux'}else os='Unknown'}const mobileHint=h('sec-ch-ua-mobile');const deviceType=/iPad|Tablet/.test(userAgent)?'Tablet':mobileHint==='?1'||/Mobile|Android|iPhone/.test(userAgent)?'Mobile':'Desktop';if(!browser)browser='Unknown';const deviceLabel=[deviceType,`${browser}${browserVersion?` ${browserVersion}`:''}`,`${os}${osVersion?` ${osVersion}`:''}`].join(' · ');return{userAgent,browser,browserVersion,os,osVersion,deviceType,deviceLabel}};const requestMeta=(event:Record<string,unknown>)=>{const headers=(event.headers||{})as Record<string,string|undefined>;const h=(name:string)=>String(headers[name]||headers[name.toLowerCase()]||headers[name.toUpperCase()]||'');const requestContext=(event.requestContext||{})as{http?:{sourceIp?:string}};const forwarded=h('x-forwarded-for').split(',')[0].trim();const ip=forwarded||String(requestContext.http?.sourceIp||h('cf-connecting-ip')||'unknown');const profile=clientProfile(headers);const decodeGeo=(value:string)=>{try{return decodeURIComponent(value)}catch{return value}};const city=decodeGeo(h('cf-ipcity')||h('x-vercel-ip-city')||h('cloudfront-viewer-city'));const region=decodeGeo(h('cf-region')||h('x-vercel-ip-country-region')||h('cloudfront-viewer-country-region-name')||h('cloudfront-viewer-country-region'));const country=decodeGeo(h('cf-ipcountry')||h('x-vercel-ip-country')||h('cloudfront-viewer-country'));const approximateLocation=city||region||country?{city,region,country}:undefined;return{ip,...profile,approximateLocation}};
const cookieMap = (event: Record<string, unknown>) => { const headers = (event.headers || {}) as Record<string, string | undefined>; const raw = String(headers.cookie || headers.Cookie || ''); return new Map(raw.split(';').map((item) => item.trim()).filter(Boolean).map((item) => { const index = item.indexOf('='); return index < 0 ? [item, ''] : [item.slice(0, index), decodeURIComponent(item.slice(index + 1))]; })); };
