/* CSP voor server-gegenereerde HTML (OAuth-callback, redirectpagina): alleen de exacte inline <script>/<style>-blokken
   van deze pagina mogen draaien (sha256-hashes), geen 'unsafe-inline', geen externe bronnen. */
const inlineHtmlCsp = (html: string) => { const hashes = (tag: string) => Array.from(html.matchAll(new RegExp(`<${tag}>([\\s\\S]*?)</${tag}>`, 'g'))).map(m => `'sha256-${createHash('sha256').update(m[1], 'utf8').digest('base64')}'`).join(' '); const scripts = hashes('script'), styles = hashes('style'); return [`default-src 'none'`, `script-src ${scripts || "'none'"}`, `style-src ${styles || "'none'"}`, `img-src 'self' data:`, `base-uri 'none'`, `object-src 'none'`, `frame-ancestors 'none'`, `form-action 'none'`].join('; '); };
const htmlRedirect = (location: string) => { const escaped = location.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;'); const html = `<!doctype html><html lang="uk"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><meta http-equiv="refresh" content="0;url=${escaped}"><title>Завершення входу</title><style>html,body{margin:0;min-height:100%;background:#07090d;color:#f5f7fb;font-family:system-ui,sans-serif}body{min-height:100vh;display:grid;place-items:center}.box{text-align:center;padding:24px}.dot{width:32px;height:32px;margin:0 auto 16px;border:3px solid #303743;border-top-color:#8ab4f8;border-radius:50%;animation:s .8s linear infinite}p{margin:0;color:#b8c0cc}@keyframes s{to{transform:rotate(360deg)}}@media(prefers-color-scheme:light){html,body{background:#f7f9fc;color:#172033}p{color:#596579}.dot{border-color:#d9dee8;border-top-color:#1a73e8}}</style></head><body><main class="box"><div class="dot" aria-hidden="true"></div><p>Завершуємо вхід… / Aanmelden wordt voltooid…</p><noscript><p><a href="${escaped}">Продовжити</a></p></noscript></main><script>window.location.replace(${JSON.stringify(location)});</script></body></html>`; return { statusCode: 200, headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store, no-cache, must-revalidate, max-age=0', Pragma: 'no-cache', 'Referrer-Policy': 'no-referrer', 'X-Content-Type-Options': 'nosniff', 'X-Frame-Options': 'DENY', 'Content-Security-Policy': inlineHtmlCsp(html) }, body: html }; }; 

const ownerFetchWithTimeout=async(url:string,init:RequestInit,timeoutCode:string)=>{const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),15000);try{return await fetch(url,{...init,signal:controller.signal})}catch{throw new Error(timeoutCode)}finally{clearTimeout(timer)}};

async function cert(kid: string) {
  const now = Date.now();
  if (!certCache || certCache.expiresAt <= now || !certCache.values[kid]) {
    const response = await ownerFetchWithTimeout('https://www.googleapis.com/oauth2/v1/certs',{},'GOOGLE_CERTIFICATE_TIMEOUT');
    if (!response.ok) throw new Error('Google certificates unavailable');
    const values = await response.json() as Record<string, string>;
    const match = /max-age=(\d+)/i.exec(response.headers.get('cache-control') || '');
    certCache = { values, expiresAt: now + Number(match?.[1] || 1800) * 1000 };
  }
  if (!certCache.values[kid]) throw new Error('Unknown Google certificate');
  return certCache.values[kid];
}

async function verifyGoogle(token: string, expectedNonce = ''): Promise<GooglePayload> {
  const parts = token.split('.');
  if (parts.length !== 3) throw new Error('Malformed credential');
  const header = decode<{ alg?: string; kid?: string }>(parts[0]);
  const payload = decode<GooglePayload>(parts[1]);
  if (header.alg !== 'RS256' || !header.kid) throw new Error('Unsupported signature');
  const signature = Buffer.from(parts[2].replace(/-/g, '+').replace(/_/g, '/'), 'base64');
  if (!verify('RSA-SHA256', Buffer.from(`${parts[0]}.${parts[1]}`), createPublicKey(await cert(header.kid)), signature)) throw new Error('Invalid signature');
  const now = Math.floor(Date.now() / 1000);
  const audienceOk = Array.isArray(payload.aud) ? payload.aud.includes(CLIENT_ID) : payload.aud === CLIENT_ID;
  if (!audienceOk || !['accounts.google.com', 'https://accounts.google.com'].includes(payload.iss)) throw new Error('Invalid issuer or audience');
  if (payload.exp <= now - 30 || (payload.nbf && payload.nbf > now + 30)) throw new Error('Expired credential');
  if (!payload.sub || (payload.email_verified !== true && payload.email_verified !== 'true') || !payload.email) throw new Error('Unverified identity');
  if (expectedNonce && payload.nonce !== expectedNonce) throw new Error('GOOGLE_NONCE_MISMATCH');
  return payload;
}

async function listOne<T>(table: string, filter: Record<string, unknown>): Promise<(T & { id: string }) | null> {
  const { items } = await db.list<T>(table, { filter });
  return (items[0] as T & { id: string } | undefined) || null;
}

const OWNER_CALLBACK_STATE_RETRY_MS=[0,75,150,300,600,1200] as const;
const ownerDelay=(ms:number)=>new Promise<void>(resolve=>setTimeout(resolve,ms));
const OWNER_STRUCTURED_STATE=/^v2\.(uk|nl)\.([A-Za-z0-9_-]{8,240})\.([A-Za-z0-9_-]{20,160})$/;
const ownerStateParts=(state:string)=>{const match=OWNER_STRUCTURED_STATE.exec(state);if(!match)return null;try{const transactionRecordId=Buffer.from(match[2],'base64url').toString('utf8');return transactionRecordId?{locale:match[1]as'uk'|'nl',transactionRecordId}:null}catch{return null}};
const ownerStateLocale=(state:string):'uk'|'nl'=>{const structured=ownerStateParts(state)?.locale;if(structured==='nl'||structured==='uk')return structured;const prefix=/^(?:v2|mailg\.v1|mailm\.v1|cloudg\.v1|gsuite\.v2)\.(uk|nl)\./.exec(state);return prefix?.[1]==='nl'?'nl':'uk'};
const ownerOAuthStateValue=(locale:'uk'|'nl',transactionRecordId:string)=>`v2.${locale}.${Buffer.from(transactionRecordId,'utf8').toString('base64url')}.${randomBytes(24).toString('base64url')}`;
async function ownerFindOAuthState(state:string){if(!state)return null;const structured=ownerStateParts(state);if(structured){const[txRaw]=await db.get<OwnerTx>(OWNER_TX_TABLE,[structured.transactionRecordId]);if(!txRaw?.oauthStateId)return null;const[stateRaw]=await db.get<OAuthState>('google_oauth_states',[txRaw.oauthStateId]);if(!stateRaw||stateRaw.stateHash!==sha(state)||stateRaw.ownerTransactionRecordId!==structured.transactionRecordId)return null;return withId(txRaw.oauthStateId,stateRaw)}for(const delay of OWNER_CALLBACK_STATE_RETRY_MS){if(delay)await ownerDelay(delay);const found=await listOne<OAuthState>('google_oauth_states',{stateHash:sha(state)});if(found)return found}return null}

