async function upsertGoogleIdentity(accountId: string, identity: GooglePayload): Promise<Identity> {
  const existing = await listOne<Identity>('account_identities', { provider: 'google', subject: identity.sub });
  if (existing && existing.accountId !== accountId) throw new Error('Google identity is already linked to another account');
  const now = Date.now();
  const record = { accountId, provider: 'google', subject: identity.sub, email: String(identity.email).toLowerCase(), emailVerified: true, displayName: identity.name || String(identity.email), picture: identity.picture || '', status: 'active' as const, createdAt: existing?.createdAt || now, updatedAt: now, lastUsedAt: now };
  if (existing) { await db.update('account_identities', [{ id: existing.id, record }]); return withId(existing.id, record); }
  const [id] = await db.add('account_identities', [record]);
  if (!id) throw new Error('Unable to link Google identity');
  await audit(accountId, 'identity_linked', { provider: 'google', identityId: id });
  return withId(id, record);
}

const activeUserBy = async (filter: Record<string, unknown>) => { const page = await db.list<User>('users', { filter }); return (page.items as User[]).find((item) => !Number(item.retiredAt || 0)) || null; };
async function retireAccount(user: User) { const now = Date.now(); const next: User = { ...user, retiredAt: now, updatedAt: now }; await alsSysteem(() => db.update('users', [{ id: user.id, record: withoutId(next) }])); const links = await db.list<Identity>('account_identities', { filter: { accountId: user.id } }); if (links.items.length) await db.delete('account_identities', links.items.map((item) => item.id)); await audit(user.id, 'account_retired', { personRef: next.personRef || personRefFor(next.email) }); return next; }
// Auth fase 1: account alleen via (provider, subject); nooit stil samenvoegen op e-mailadres.
// Beslisregels in account-koppeling.ts (besluitGoogleKoppeling / magEigenaarZijn).
async function ensureUser(identity: GooglePayload): Promise<User> {
  // userinfo kan e-mail/email_verified na verifyGoogle overschrijven: hier opnieuw eisen.
  if (!identity.sub || !identity.email || (identity.email_verified !== true && identity.email_verified !== 'true')) throw new Error('Unverified identity');
  const email = String(identity.email).toLowerCase();
  const linked = await listOne<Identity>('account_identities', { provider: 'google', subject: identity.sub });
  // Fase 3: ontkoppelde (uitgeschakelde) Google-identiteit meldt niet aan, ook niet via de oude users.sub-route.
  if (linked && linked.status === 'disabled') throw new Error('IDENTITY_DISABLED');
  let linkedUser: User | null = null;
  if (linked) { const [raw] = await db.get<User>('users', [linked.accountId]); if (raw && !Number(raw.retiredAt || 0)) linkedUser = withId(linked.accountId, raw); }
  const subUser = linkedUser ? null : await activeUserBy({ sub: identity.sub });
  const emailUser = linkedUser || subUser ? null : await activeUserBy({ email });
  const emailUserGoogle = emailUser ? (await db.list<Identity>('account_identities', { filter: { accountId: emailUser.id, provider: 'google' }, limit: 1 })).items.length > 0 : false;
  const besluit = besluitGoogleKoppeling({ identiteitAccountId: linkedUser?.id || '', subAccountId: subUser?.id || '', emailAccountId: emailUser?.id || '', emailAccountHeeftGoogleIdentiteit: emailUserGoogle, email, eigenaarEmail: OWNER });
  let existing: User | null = besluit.soort === 'bestaand' ? (linkedUser || subUser || emailUser) : null;
  if (existing && existing.status === 'deleted' && accountRecoveryExpired(existing)) { await retireAccount(existing); existing = null; }
  // Audit-fix 10: geblokkeerd account krijgt bij aanmelden geen sessie, ook niet met OWNER_EMAIL (vroeger
  // uitgezonderd: wie de mailbox van de eigenaar overnam, omzeilde zo een blokkade). Deblokkeren: RUNBOOK-AUDIT-FIXES.md.
  if (existing && existing.status === 'blocked') { await audit(existing.id, 'sign_in_refused_blocked', { provider: 'google' }); throw new Error('ACCOUNT_BLOCKED'); }
  // Audit-fix 10: eerst verouderde eigenaars (role owner, ander adres) degraderen, zodat er nooit twee eigenaars zijn.
  if (isOwnerEmail(email)) await alsSysteem(() => verouderdeEigenarenIntrekken()).catch(() => []);
  const ownerRow = isOwnerEmail(email) ? await activeUserBy({ role: 'owner' }) : null;
  const now = Date.now();
  if (existing) {
    const owner = magEigenaarZijn({ email, eigenaarEmail: OWNER, accountId: existing.id, bestaandEigenaarId: ownerRow?.id || '' });
    const next: User = { ...existing, email, sub: identity.sub, name: identity.name || existing.name || email, picture: existing.customPicture ? existing.picture : identity.picture || existing.picture || '', role: owner ? 'owner' : existing.role === 'owner' ? 'member' : existing.role || 'member', personRef: existing.personRef || personRefFor(email), status: existing.status === 'deleted' ? 'deleted' : owner ? 'approved' : existing.status, accessLevel: owner ? 'full' : existing.accessLevel, updatedAt: now }; 
    if (existing.role === 'owner' && !owner) await audit(existing.id, 'owner_role_demoted_stale', { reden: 'not OWNER_EMAIL of tweede eigenaar' });
    await alsSysteem(() => db.update('users', [{ id: existing!.id, record: withoutId(next) }]));
    await upsertGoogleIdentity(existing.id, identity);
    await audit(existing.id, besluit.soort === 'bestaand' && besluit.reden === 'eigenaar-eerste-koppeling' ? 'owner_first_google_binding' : 'sign_in', { provider: 'google' });
    return next;
  }
  const owner = magEigenaarZijn({ email, eigenaarEmail: OWNER, accountId: '', bestaandEigenaarId: ownerRow?.id || '' });
  const record = { email, sub: identity.sub, name: identity.name || email, picture: identity.picture || '', personRef: personRefFor(email), role: owner ? 'owner' as const : 'member' as const, status: owner ? 'approved' as const : 'new' as const, accessLevel: 'full' as const, createdAt: now, updatedAt: now };
  const [id] = await db.add('users', [record]);
  if (!id) throw new Error('Unable to create user');
  await upsertGoogleIdentity(id, identity);
  await audit(id, 'account_created', { provider: 'google', ...(besluit.soort === 'nieuw' && besluit.emailConflictAccountId ? { emailSharedWithExistingAccount: true } : {}) });
  if (besluit.soort === 'nieuw' && besluit.emailConflictAccountId) await meldEmailConflict(besluit.emailConflictAccountId, id, email);
  return withId(id, record);
}

