const safePicture=(value:unknown)=>{const raw=String(value||'').trim();if(/^data:image\/(?:jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(raw)&&raw.length<=340000)return raw;try{const url=new URL(raw),host=url.hostname.toLowerCase();if(url.protocol!=='https:'||url.username||url.password||!(host==='lh3.googleusercontent.com'||host.endsWith('.googleusercontent.com')))return'';url.hash='';return url.toString()}catch{return''}};const ownerUploadedPicture=(data:unknown,mime:unknown)=>{const value=String(data||''),mimeType=String(mime||'');if(!['image/jpeg','image/png','image/webp'].includes(mimeType)||!value||value.length>330000||!/^[A-Za-z0-9+/=]+$/.test(value))return'';const bytes=Buffer.from(value,'base64');if(bytes.length<12||bytes.length>240000)return'';const jpeg=mimeType==='image/jpeg'&&bytes[0]===255&&bytes[1]===216&&bytes[2]===255,png=mimeType==='image/png'&&bytes[0]===137&&bytes[1]===80&&bytes[2]===78&&bytes[3]===71,webp=mimeType==='image/webp'&&bytes.subarray(0,4).toString('ascii')==='RIFF'&&bytes.subarray(8,12).toString('ascii')==='WEBP';return jpeg||png||webp?`data:${mimeType};base64,${value}`:''};const publicUser = (user: User) => ({ id: user.id, accountId: user.id, email: user.email, name: user.name, picture: safePicture(user.picture), customPicture: Boolean(user.customPicture), role: user.role, workspaceRole:canonicalWorkspaceRole(user), permissions:permissionsFor(user), status: user.status, accessLevel: user.accessLevel, entitlements:normalizeIdentityEntitlements(user.entitlements), deletedAt: user.deletedAt || 0, personRef: user.personRef || personRefFor(user.email), recoverableUntil: user.recoverableUntil || 0, retiredAt: user.retiredAt || 0, recoveryDays: ACCOUNT_RECOVERY_DAYS });
