async function serviceSessionContext(body: unknown, expectedService?: ServiceId): Promise<{ session: ServiceSession; user: User } | null> { const data = (body || {}) as Record<string, unknown>; const token = String(data.serviceSessionToken || ''); const service = resolveService(data.service); if (!token || !service || (expectedService && service !== expectedService)) return null; const current = await listOne<ServiceSession>('service_sessions', { tokenHash: sha(token), service }); if (!current || current.expiresAt <= Date.now()) return null; const [raw] = await db.get<User>('users', [current.userId]); if (!raw) return null; let session = current; if (current.expiresAt - Date.now() < SERVICE_SESSION_REFRESH_MS || !current.lastSeenAt || Date.now() - current.lastSeenAt > 5 * 60 * 1000) { const record = withoutId({ ...current, expiresAt: current.expiresAt - Date.now() < SERVICE_SESSION_REFRESH_MS ? Date.now() + SERVICE_SESSION_MS : current.expiresAt, lastSeenAt: Date.now(), updatedAt: Date.now() }); await db.update('service_sessions', [{ id: current.id, record }]); session = withId(current.id, record); } return { session, user: withId(current.userId, raw) }; }
