const clearedServiceCookie = (service: Exclude<ServiceId, 'hub'>, tabId: string) => `${serviceCookieName(service, tabId)}=; ${OWNER_COOKIE_SCOPE}; Max-Age=0; HttpOnly; Secure; SameSite=Strict`;
