async function accountOverviewData(user: User) { const ownedAll = await listOwnedWorkspaces(user.id); const activeOwned = ownedAll.filter((item) => !Number(item.archivedAt || 0)); const memberships = await db.list<Member>('workspace_members', { filter: { userId: user.id, status: 'active' } }); const sharedIds = [...new Set(memberships.items.map((item) => item.workspaceId))]; const sharedRaw = sharedIds.length ? await db.get<Workspace>('workspaces', sharedIds) : []; const workspaces = [...activeOwned.map((item) => ({ id: item.id, name: item.name, ownerUserId: item.ownerUserId, shared: false })), ...sharedRaw.flatMap((item, index) => item && !Number(item.archivedAt || 0) ? [{ id: sharedIds[index], name: item.name, ownerUserId: item.ownerUserId, shared: true }] : [])]; const notificationState=await siteNotificationOverview(user); return { user: publicUser(user), ...notificationState, workspaces, activeWorkspaces: activeOwned.map((item) => ({ id: item.id, name: item.name })), archivedWorkspaces: ownedAll.filter((item) => Number(item.archivedAt || 0) > 0).map((item) => ({ id: item.id, name: item.name, archivedAt: Number(item.archivedAt || 0) })) }; }
async function adminOverviewData() { const requests = await db.list('access_requests', { filter: { status: 'pending' } }); const users = await db.list<User>('users'); return { requests: requests.items.sort((a, b) => Number(b.requestedAt) - Number(a.requestedAt)), users: users.items.map(publicUser) }; }
async function decideAccessRequest(requestId: string, decision: string, actorId: string) { const [request] = await db.get<Record<string, unknown>>('access_requests', [requestId]); if (!request) return null; const userId = String(request.userId || ''); const [raw] = await db.get<User>('users', [userId]); if (!raw) return null; const user = withId(userId, raw); const granted=grantFromDecision(decision); const approved=granted.status==='approved'; const next={...user,...granted,updatedAt:Date.now()}; await db.update('users', [{ id: next.id, record: withoutId(next) }]); await db.update('access_requests', [{ id: requestId, record: { ...request, status: approved ? 'approved' : 'denied', decision, decidedAt: Date.now() } }]); if (approved) { await ensureWorkspace(next); await activateInvites(next); } await notify(next.id, next.email, 'access_decision', approved ? 'Доступ схвалено' : 'Рішення щодо доступу', approved ? 'Ваш особистий простір готовий.' : 'Доступ поки не схвалено.'); await audit(actorId, 'admin_access_request_decided', { targetUserId: next.id, decision }); return publicUser(next); }
async function updateManagedUser(userId: string, statusValue: unknown, accessValue: unknown, actorId: string, entitlementsValue?:unknown, roleValue?:unknown) { const [raw] = await db.get<User>('users', [userId]); if (!raw) return null; const user = withId(userId, raw); if (isOwnerEmail(user.email) || user.role === 'owner') throw new Error('OWNER_PROTECTED'); const requested=String(roleValue||''); const role:User['role']=requested==='admin'?'admin':requested==='viewer'||accessValue==='limited'?'viewer':requested==='member'?'member':(user.role as string)==='owner'?'member':(user.role||'member'); if((role as string)==='owner') throw new Error('OWNER_PROTECTED'); const [actorRaw]=actorId?await db.get<User>('users',[actorId]):[null]; if(actorRaw&&!canManageRole(withId(actorId,actorRaw),role==='admin'?'admin':role==='viewer'?'viewer':'member')) throw new Error('RBAC_ROLE_FORBIDDEN'); const status: Status = ['new', 'approved', 'blocked'].includes(String(statusValue)) ? String(statusValue) as Status : user.status; const accessLevel: Level = role==='viewer' || accessValue === 'limited' ? 'limited' : 'full'; const entitlements=entitlementsValue===undefined?normalizeIdentityEntitlements(user.entitlements):normalizeIdentityEntitlements(entitlementsValue); const next = { ...user, status, accessLevel, role, entitlements, updatedAt: Date.now() }; await db.update('users', [{ id: next.id, record: withoutId(next) }]); if (status === 'blocked' && user.status !== 'blocked') await accountSessiesIntrekken(next.id, 'account-blocked'); if (status === 'approved' && user.status === 'blocked') await aiGrants.unblockUser(next.id, actorId || 'system'); if (status === 'approved') { await ensureWorkspace(next); await activateInvites(next); } await audit(actorId, 'admin_user_access_changed', { targetUserId: next.id, status, accessLevel, role, entitlements }); return publicUser(next); }
async function deleteManagedUser(userId: string, confirmEmail: string, actorId: string) { const [raw] = await db.get<User>('users', [userId]); if (!raw) return null; const user = withId(userId, raw); if (isOwnerEmail(user.email)) throw new Error('OWNER_PROTECTED'); if (confirmEmail.trim().toLowerCase() !== user.email) throw new Error('EMAIL_MISMATCH'); const next = await deleteRecoverably(user, 'admin'); await audit(actorId, 'admin_user_deleted_recoverably', { targetUserId: next.id }); return publicUser(next); }
