async function ownerRequireAnchor(event:Record<string,unknown>,body:unknown):Promise<OwnerAnchorSuccess|OwnerSessionFailure>{const service=ownerService(event,body);const tab=ownerTab(body);if(!service)return{errorCode:'OWNER_SESSION_CONTEXT_REQUIRED'}as const;const cookies=cookieMap(event);let cookieValue=String(cookies.get(OWNER_ECOSYSTEM_COOKIE)||'');let token=ownerSessionCookieParts(cookieValue).token;let session=await ownerFindSession(cookieValue);let legacy=false;if(!session&&tab){const legacyToken=String(cookies.get(ownerCookieName(service,tab))||'');const legacySession=await ownerFindSession(legacyToken);if(legacySession){cookieValue=legacyToken;token=ownerSessionCookieParts(legacyToken).token;session=legacySession;legacy=true}}const now=Date.now();if(!session||session.revokedAt)return{errorCode:'OWNER_SESSION_INVALID',service,tab}as const;if(session.scope!=='ecosystem'&&(!legacy||session.service!==service||session.tabHash!==sha(tab)))return{errorCode:'OWNER_SESSION_INVALID',service,tab}as const;if(session.idleExpiresAt<=now||session.absoluteExpiresAt<=now)return{errorCode:'OWNER_SESSION_EXPIRED',service,tab}as const;const rev=await ownerRevocation(session.userId);if(session.revocationEpoch<(rev?.epoch||0))return{errorCode:'OWNER_SESSION_REVOKED',service,tab}as const;const[user]=await db.get<User>('users',[session.userId]);if(!user)return{errorCode:'OWNER_USER_NOT_FOUND',service,tab}as const;Object.assign(user,await eigenaarRolBijwerken(session.userId,user));if(accountGeweigerd(user))return{errorCode:'OWNER_ACCOUNT_BLOCKED',service,tab}as const;sessieGeverifieerd();return{session,service,tab,token,user:withId(session.userId,user),legacy}as const}
