export const googleSuiteSyncCron=async(event:{payload?:{accountLimit?:number}})=>{try{const limit=Number(event.payload?.accountLimit||10),drive=await runGoogleSuiteDriveSync(limit),calendar=await runGoogleSuiteCalendarSync(limit);return{statusCode:200,body:JSON.stringify({ok:true,drive,calendar})}}catch(caught){const reason=caught instanceof Error&&caught.message.startsWith('GOOGLE_SUITE_')?caught.message:'GOOGLE_SUITE_SYNC_CRON_FAILED';console.error('Google Suite sync cron failed',{reason});return{statusCode:200,body:JSON.stringify({ok:false,reason})}}};

export const mailMaintenanceCron=async(event:{payload?:{batchLimit?:number}})=>{try{const platform=await mailPlatformStatus(true),batchLimit=Math.max(1,Math.min(3,Number(event.payload?.batchLimit||3))),stateOutbox=await runGoogleSuiteMailStateOutbox(batchLimit*10),principalRows=await db.list<Record<string,unknown>>('provider_principals_v1',{limit:1000}),bplusOwners=[...new Set(principalRows.items.map(item=>String(item.ownerUserId||'')).filter(Boolean))];const bulkStateOutbox=[] as Array<{ownerHash:string;results:unknown}>;for(const ownerUserId of bplusOwners){await mailMigrateBplusOwner(ownerUserId);try{bulkStateOutbox.push({ownerHash:sha(ownerUserId).slice(0,12),results:await runGoogleSuiteMailBulkStateOutbox(ownerUserId,batchLimit)})}catch(caught){bulkStateOutbox.push({ownerHash:sha(ownerUserId).slice(0,12),results:{errorCode:caught instanceof Error?caught.message:'GOOGLE_MAIL_BULK_STATE_CRON_FAILED'}})}}const rows=await db.list<Omit<MailAccountRecord,'id'>>(MAIL_ACCOUNTS_TABLE,{limit:1000}),allOwners=[...new Set((rows.items as MailAccountRecord[]).filter(item=>['initial_sync','connected','degraded'].includes(item.status)).filter(item=>item.provider==='google'?item.tokenSource==='google_oauth_grant_v1'||platform.providers.google.runtimeEnabled:platform.providers.microsoft.runtimeEnabled).map(item=>item.ownerUserId))],recentSessionRows=await db.list<{userId:string;lastSeenAt:number}>(OWNER_SESSION_TABLE,{limit:5000}),activeOwnerIds=new Set(recentSessionRows.items.filter(item=>Number(item.lastSeenAt||0)>=Date.now()-7*24*60*60*1000).map(item=>String(item.userId||''))),owners=allOwners.filter(ownerUserId=>activeOwnerIds.has(ownerUserId)),dormantSkipped=allOwners.length-owners.length,results:unknown[]=[];for(const ownerUserId of owners){try{const recovered=await mailRecoverStaleJobs(ownerUserId),purged=await mailPurgeJobs(ownerUserId),scheduled=await mailScheduleMaintenance(ownerUserId),jobs=await mailRunDueJobs(ownerUserId,batchLimit);results.push({ownerHash:sha(ownerUserId).slice(0,12),recovered,purged,scheduled,jobs})}catch(caught){const reason=caught instanceof Error&&caught.message.startsWith('MAIL_')?caught.message:'MAIL_MAINTENANCE_OWNER_FAILED';results.push({ownerHash:sha(ownerUserId).slice(0,12),reason})}}try{await adminWriteSingleton('cron_status_mail_maintenance_v1','global',{lastRunAt:Date.now(),ok:true,ownersTotal:allOwners.length,ownersProcessed:owners.length,dormantSkipped,bplusOwners:bplusOwners.length,reason:''})}catch{}return{statusCode:200,body:JSON.stringify({ok:true,stateOutbox,bulkStateOutbox,activeProviders:Number(platform.providers.google.runtimeEnabled)+Number(platform.providers.microsoft.runtimeEnabled),bplusOwners:bplusOwners.length,owners:owners.length,dormantSkipped,results})}}catch(caught){const reason=caught instanceof Error&&caught.message.startsWith('MAIL_')?caught.message:'MAIL_MAINTENANCE_CRON_FAILED';console.error('Mail maintenance cron failed',{reason});try{await adminWriteSingleton('cron_status_mail_maintenance_v1','global',{lastRunAt:Date.now(),ok:false,reason})}catch{}return{statusCode:200,body:JSON.stringify({ok:false,reason})}}};

