/** Cron-taak (elke minuut): uitgestelde mail uit app.mail_queue versturen. Zie backend/mail-compose.ts en migratie 0016. */
export const mailQueueCron = async (): Promise<{ statusCode: number; body: string }> => {
  try { return { statusCode: 200, body: JSON.stringify({ ok: true, ...(await runMailQueue(10)) }) }; }
  catch (caught) { console.error('Mail queue cron failed', { reason: caught instanceof Error ? caught.message : 'MAIL_QUEUE_CRON_FAILED' }); return { statusCode: 200, body: JSON.stringify({ ok: false, reason: caught instanceof Error ? caught.message.slice(0, 120) : 'MAIL_QUEUE_CRON_FAILED' }) }; }
};
